var builder = WebApplication.CreateBuilder(args);

builder.Services.AddControllers();

// Register API Versioning services
builder.Services.AddApiVersioning(options =>
{
    // Return the supported versions in a response header
    options.ReportApiVersions = true;

    // Use version 1.0 when the client does not specify a version
    options.DefaultApiVersion = new ApiVersion(1, 0);
    options.AssumeDefaultVersionWhenUnspecified = true;

    // Accept versions via URL segment, query string, or header
    options.ApiVersionReader = ApiVersionReader.Combine(
        new UrlSegmentApiVersionReader(),
        new QueryStringApiVersionReader("api-version"),
        new HeaderApiVersionReader("X-Api-Version")
    );
});

var app = builder.Build();
app.MapControllers();
app.Run();

using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Versioning;

[ApiController]
[Route("api/v{version:apiVersion}/[controller]")]
[ApiVersion("1.0")]
[ApiVersion("2.0")]
public class ProductsController : ControllerBase
{
    private readonly IProductService _v1Service;
    private readonly IProductServiceV2 _v2Service;

    public ProductsController(
        IProductService v1Service,
        IProductServiceV2 v2Service)
    {
        _v1Service = v1Service;
        _v2Service = v2Service;
    }

    // GET /api/v1/products — returns V1 DTO
    [HttpGet]
    [MapToApiVersion("1.0")]
    public async Task<ActionResult<IEnumerable<ProductV1Dto>>> GetV1()
        => Ok(await _v1Service.GetAllAsync());

    // GET /api/v2/products — returns V2 DTO with extra fields
    [HttpGet]
    [MapToApiVersion("2.0")]
    public async Task<ActionResult<IEnumerable<ProductV2Dto>>> GetV2()
        => Ok(await _v2Service.GetAllAsync());
}

// Supported versions are returned in the API-Supported-Versions response header

builder.Services.AddApiVersioning(options =>
{
    options.ReportApiVersions = true;
    options.DefaultApiVersion = new ApiVersion(2, 0);
    options.AssumeDefaultVersionWhenUnspecified = true;
});

[ApiController]
[Route("api/v{version:apiVersion}/[controller]")]
// Version 1.0 is marked as deprecated
[ApiVersion("1.0", Deprecated = true)]
[ApiVersion("2.0")]
public class ProductsController : ControllerBase
{
    // Clients will see the 'Api-Version' and
    // 'Deprecated-API-Version' response headers
    [HttpGet]
    [MapToApiVersion("1.0")]
    public async Task<ActionResult<IEnumerable<ProductV1Dto>>> GetV1()
    {
        // Still functional, but clients are warned
        // to migrate to v2.0
        return Ok(await _v1Service.GetAllAsync());
    }
}

